def nest(lang):
    out = {}
    for key, (en, ne) in sorted(T.items()):
        parts = key.split('.')
        d = out
        for p in parts[:-1]:
            d = d.setdefault(p, {})
        d[parts[-1]] = en if lang == 'en' else ne
    return out

here = os.path.dirname(os.path.abspath(__file__))
for lang in ('en', 'ne'):
    with open(os.path.join(here, '..', 'src', 'i18n', f'{lang}.json'), 'w', encoding='utf-8') as f:
        json.dump(nest(lang), f, ensure_ascii=False, indent=2)
        f.write('\n')
print(len(T), 'keys written')
